begin;
create function pg_temp.check_activity(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'Activity log: %',label;end if;end $$;
insert into auth.users(id,email) values('a1111111-1111-4111-8111-111111111111','audit-admin@example.test');
insert into public.social_admins(user_id,email,role,is_active,first_name,last_name,username,suite_role_key) values('a1111111-1111-4111-8111-111111111111','audit-admin@example.test','admin',true,'Audit','Admin','audad','admin');
select pg_temp.check_activity((select count(*) from private.suite_activity_log)=(select count(*) from private.cashbook_entries)+(select count(*) from private.cashbook_settlement_events)+(select count(*) from private.trainer_audit),'backfill uses every actual source event once');
set local role service_role;
do $$
declare admin_id uuid:='a1111111-1111-4111-8111-111111111111';trainer private.cashbook_accounts;cashier private.cashbook_accounts;result jsonb;first_page jsonb;next_page jsonb;payload jsonb;operation uuid;booking uuid;team uuid;target uuid;v bigint;before_count bigint;session uuid:=gen_random_uuid();
begin
 select * into trainer from private.cashbook_accounts where username='jentm';select * into cashier from private.cashbook_accounts where username='barow';select id into team from public.social_teams where slug='u19-junioren';
 result:=public.suite_activity_request(trainer.suite_user_id,'{}');perform pg_temp.check_activity(result->>'status'='403','ordinary users cannot read activity');
 result:=public.suite_activity_request(admin_id,'{"from":"2026-10-32"}');perform pg_temp.check_activity(result->>'status'='400','invalid dates rejected');
 result:=public.suite_activity_request(admin_id,'{"from":"2026-10-12","until":"2026-10-11"}');perform pg_temp.check_activity(result->>'status'='400','reversed dates rejected');
 result:=public.suite_activity_request(admin_id,'{"category":"anything"}');perform pg_temp.check_activity(result->>'status'='400','unknown categories rejected');
 result:=public.suite_record_login(trainer.suite_user_id,session,'2026-10-10 10:00+02');perform pg_temp.check_activity(not result ? 'error','verified login recorded');
 perform public.suite_record_login(trainer.suite_user_id,session,'2026-10-10 10:00+02');
 perform pg_temp.check_activity((select count(*)=1 from private.suite_activity_log where source_key='session:'||session),'reload and token refresh do not duplicate login');
 update public.social_admins set is_blocked=true where user_id=trainer.suite_user_id;
 result:=public.suite_record_login(trainer.suite_user_id,gen_random_uuid(),now());perform pg_temp.check_activity(result->>'status'='403','blocked sessions do not record successful login');
 update public.social_admins set is_blocked=false where user_id=trainer.suite_user_id;
 -- Exact Berlin date boundaries, including the daylight-saving transition.
 perform public.suite_record_login(trainer.suite_user_id,gen_random_uuid(),'2026-03-28 23:00:00+00');
 perform public.suite_record_login(trainer.suite_user_id,gen_random_uuid(),'2026-03-29 21:59:59+00');
 perform public.suite_record_login(trainer.suite_user_id,gen_random_uuid(),'2026-03-29 22:00:00+00');
 result:=public.suite_activity_request(admin_id,jsonb_build_object('userId',trainer.suite_user_id,'category','auth','from','2026-03-29','until','2026-03-29'));
 perform pg_temp.check_activity(jsonb_array_length(result->'entries')=2,'dates include a whole Berlin calendar day across DST');
 operation:=gen_random_uuid();payload:=jsonb_build_object('action','book','requestId',operation,'direction','deposit','amountCents',25000,'confirmed',true,'evidenceHash',repeat('a',64),'evidencePath',cashier.id||'/'||operation||'/photo');
 result:=public.cashbook_request(cashier.suite_user_id,payload);perform pg_temp.check_activity(not result ? 'error','deposit accepted');booking:=(result->>'entryId')::uuid;
 perform public.cashbook_request(cashier.suite_user_id,payload);
 perform pg_temp.check_activity((select count(*)=1 from private.suite_activity_log where source_key='cashbook:'||booking and event='cashbook_deposit' and actor_id=cashier.suite_user_id and metadata->>'amountCents'='25000'),'deposit audit atomic and idempotent');
 operation:=gen_random_uuid();payload:=jsonb_build_object('action','book','requestId',operation,'direction','withdrawal','amountCents',2000,'teamId',team,'confirmed',true,'evidenceHash',repeat('3',64),'signatureHash',repeat('4',64),'evidencePath',trainer.id||'/'||operation||'/receipt','signaturePath',trainer.id||'/'||operation||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,payload);perform pg_temp.check_activity(not result ? 'error','withdrawal accepted');booking:=(result->>'entryId')::uuid;
 operation:=gen_random_uuid();payload:=payload||jsonb_build_object('action','edit','id',booking,'amountCents',1800,'reason','Betrag berichtigt','requestId',operation,'signaturePath',trainer.id||'/'||operation||'/signature');
 result:=public.cashbook_change_request(trainer.suite_user_id,payload);perform pg_temp.check_activity(not result ? 'error','correction accepted');booking:=(result->>'entryId')::uuid;
 perform pg_temp.check_activity((select event='cashbook_corrected' and metadata->>'amountCents'='1800' and metadata->>'previousAmountCents'='2000' and metadata->>'safeDeltaCents'='200' from private.suite_activity_log where source_key='cashbook:'||booking),'correction distinguishes revised amount from cash movement');
 operation:=gen_random_uuid();payload:=payload||jsonb_build_object('action','cancel','id',booking,'reason','Doppelt erfasst','requestId',operation,'signaturePath',trainer.id||'/'||operation||'/signature');
 result:=public.cashbook_change_request(trainer.suite_user_id,payload);perform pg_temp.check_activity(not result ? 'error','cancellation accepted');booking:=(result->>'entryId')::uuid;
 perform pg_temp.check_activity((select event='cashbook_cancelled' and metadata->>'amountCents'='0' and metadata->>'previousAmountCents'='1800' from private.suite_activity_log where source_key='cashbook:'||booking),'cancellation retains previous amount');
 operation:=gen_random_uuid();payload:=jsonb_build_object('action','book','requestId',operation,'direction','advance','amountCents',2300,'teamId',team,'confirmed',true,'notificationEmail','test@example.org','evidenceHash',repeat('6',64),'signatureHash',repeat('7',64),'evidencePath',trainer.id||'/'||operation||'/receipt','signaturePath',trainer.id||'/'||operation||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,payload);perform pg_temp.check_activity(not result ? 'error','advance accepted');booking:=(result->>'entryId')::uuid;
 perform pg_temp.check_activity((select metadata->>'safeDeltaCents'='0' from private.suite_activity_log where source_key='cashbook:'||booking),'advance does not claim safe withdrawal');
 result:=public.cashbook_settlement_request(cashier.suite_user_id,jsonb_build_object('action','mark_transferred','confirmed',true,'id',booking,'requestId',gen_random_uuid()));
 perform pg_temp.check_activity(not result ? 'error','transfer accepted');
 result:=public.cashbook_settlement_request(trainer.suite_user_id,jsonb_build_object('action','confirm_received','confirmed',true,'id',booking,'requestId',gen_random_uuid()));
 perform pg_temp.check_activity(not result ? 'error','receipt accepted');
 perform pg_temp.check_activity((select count(*)=2 from private.suite_activity_log where event in ('cashbook_transferred','cashbook_received') and metadata->>'amountCents'='2300'),'both reimbursement actors recorded');
 select person_id,version into target,v from private.trainer_profiles limit 1;
 result:=public.trainer_management_request(admin_id,jsonb_build_object('action','set_active','personId',target,'version',v,'active',false));perform pg_temp.check_activity(not result ? 'error','passivation accepted');
 perform pg_temp.check_activity(exists(select 1 from private.suite_activity_log where actor_id=admin_id and event='trainer_passive'),'trainer audit captured');
 select count(*) into before_count from private.suite_activity_log;
 result:=public.suite_users_request(trainer.suite_user_id,jsonb_build_object('action','bulk_state','operation','block','userIds',jsonb_build_array(cashier.suite_user_id)));
 perform pg_temp.check_activity(result->>'status'='403' and (select count(*)=before_count from private.suite_activity_log),'failed actions do not claim success');
 result:=public.suite_users_request(admin_id,jsonb_build_object('action','bulk_state','operation','block','userIds',jsonb_build_array(cashier.suite_user_id)));
 perform pg_temp.check_activity(not result ? 'error' and exists(select 1 from private.suite_activity_log where actor_id=admin_id and event='user_blocked' and metadata->>'subjectId'=cashier.suite_user_id::text),'bulk action recorded per target');
 result:=public.suite_users_request(admin_id,jsonb_build_object('action','prepare_delete','userIds',jsonb_build_array(cashier.suite_user_id)));
 result:=public.suite_users_request(admin_id,jsonb_build_object('action','finish_delete','userId',cashier.suite_user_id));
 perform pg_temp.check_activity(not result ? 'error' and exists(select 1 from private.suite_activity_log where event='user_deleted' and metadata->>'subjectId'=cashier.suite_user_id::text),'successful deletion retains target snapshot');
 perform pg_temp.check_activity(exists(select 1 from private.suite_activity_log where event='cashbook_deposit' and actor_id=cashier.suite_user_id and actor_name<>''),'deleting user retains financial attribution');
 for i in 1..55 loop perform public.suite_record_login(trainer.suite_user_id,gen_random_uuid(),'2026-10-09 10:00+02');end loop;
 first_page:=public.suite_activity_request(admin_id,jsonb_build_object('userId',trainer.suite_user_id,'category','auth','from','2026-10-09','until','2026-10-09'));
 next_page:=public.suite_activity_request(admin_id,jsonb_build_object('userId',trainer.suite_user_id,'category','auth','from','2026-10-09','until','2026-10-09','cursor',first_page->'nextCursor'));
 perform pg_temp.check_activity(jsonb_array_length(first_page->'entries')=50 and jsonb_array_length(next_page->'entries')=5 and next_page->'nextCursor'='null'::jsonb,'stable cursor handles same timestamp');
 perform pg_temp.check_activity(not exists(select 1 from jsonb_array_elements(first_page->'entries') a,jsonb_array_elements(next_page->'entries') b where a->>'id'=b->>'id'),'no duplicated pagination rows');
 perform pg_temp.check_activity(not exists(select 1 from private.suite_activity_log where metadata ?| array['password','signaturePath','evidencePath','email','street','before_data','after_data','sessionId']),'no sensitive event payloads');
end $$;
reset role;
select pg_temp.check_activity(not has_function_privilege('anon','public.suite_activity_request(uuid,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.suite_activity_request(uuid,jsonb)','EXECUTE'),'browser cannot bypass API authorization');
select pg_temp.check_activity(not has_function_privilege('authenticated','public.suite_record_login(uuid,uuid,timestamptz)','EXECUTE'),'browser cannot forge logins');
select pg_temp.check_activity(not has_table_privilege('authenticated','private.suite_activity_log','SELECT') and not has_table_privilege('anon','private.suite_activity_log','SELECT'),'no public log access');
select pg_temp.check_activity(not has_table_privilege('service_role','private.suite_activity_log','UPDATE') and not has_table_privilege('service_role','private.suite_activity_log','DELETE'),'events append only');
rollback;
